static z_t54_t z_t59_replaceFirst(
    const z_t59_t* self, const z_t59_t* needle,
    const z_t59_t* replacement) {
    return z_t59_replace_impl(self, needle, replacement, true);
}

static z_t54_t z_t59_repeated(const z_t59_t* self, uint64_t n);
static z_t54_t z_t59_repeated(const z_t59_t* self, uint64_t n) {
    z_t54_t z = {0};
    uint64_t total = self->size * n;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    for (uint64_t i = 0; i < n; i++) {
        memcpy(z.data + i * self->size, self->data, self->size);
    }
    z.data[total] = '\0';
    return z;
}

static z_t54_t z_t59_concat(
    const z_t59_t* self, const z_t59_t* other);
