static const z_t5695_t _zag3171 = { { .data = "create", .size = 6 }, { .data = "", .size = 0 }, { .length = 4, .data = _zag3170 }, { .data = "static z_@@NAME@@_t z_@@NAME@@_create(uint64_t count) {\n    z_@@NAME@@_t br;\n    br.b = (z_@@NAME@@_blk*)z_xmalloc(sizeof(z_@@NAME@@_blk));\n    if (z_mutex_init(&br.b->m) != 0 || z_cond_init(&br.b->c) != 0) {\n        z_panic(\"sync.Barrier: the operating system could not make a lock\");\n    }\n    br.b->count = count == 0 ? 1 : count;\n    br.b->waiting = 0;\n    br.b->round = 0;\n    atomic_init(&br.b->refs, 1);\n    return br;\n}", .size = 427 } };
